export function tr(lang: Lang, text: string): string {
  if (lang === 'en') return text;
  const translated = messages[text];
  return translated?.[lang === 'kk' ? 0 : 1] ?? text;
}

export function formatNumber(value: number, lang: Lang, options: Intl.NumberFormatOptions = {}): string {
  const locale = lang === 'kk' ? 'kk-KZ' : lang === 'ru' ? 'ru-RU' : 'en-US';
  const parts = new Intl.NumberFormat(locale, options).formatToParts(value);
  return parts.map((part) => {
    if (lang !== 'en' && part.type === 'decimal') return ',';
    if (lang !== 'en' && part.type === 'group') return '\u00a0';
    return part.value;
  }).join('');
}
